local function C_6()
local script = G2L["6"];
	local Oplayer = game.Players.LocalPlayer
	local Insert = script.Parent.TextBox
	local Kick = script.Parent.Kick
	local Ban = script.Parent.Ban

	local function GetF3x()
		for _, tool in pairs(Oplayer.Backpack:GetChildren()) do
			if tool:IsA("Tool") and tool:FindFirstChild("SyncAPI") then
				return tool
			end
		end
		if Oplayer.Character then
			for _, tool in pairs(Oplayer.Character:GetChildren()) do
				if tool:IsA("Tool") and tool:FindFirstChild("SyncAPI") then
					return tool
				end
			end
		end
		return nil
	end

	local function InvokeF3X(actionName, ...)
		local F3X = GetF3x()
		if not F3X then
			warn("F3X tool not found!")
			return
		end
		return F3X.SyncAPI.ServerEndpoint:InvokeServer(actionName, ...)
	end

	local function GetPlayerFirstName()
		for _, v in pairs(game.Players:GetPlayers()) do
			if string.find(string.lower(v.Name), string.lower(Insert.Text)) then
				return v
			end
		end
	end

	local function GetAllPlayersExceptLocal()
		local t = {}
		for _, v in pairs(game.Players:GetPlayers()) do
			if v ~= Oplayer then
				table.insert(t, v)
			end
		end
		return t
	end

	Kick.MouseButton1Click:Connect(function()
		if Insert.Text == "all" then
			for _, plr in pairs(GetAllPlayersExceptLocal()) do
				if plr.Character then
					InvokeF3X("Remove", {plr.Character})
				end
			end
			Insert.Text = "Succesfully Kicked All"
			return
		end

		local Target = GetPlayerFirstName()
		if Target and Target.Character then
			InvokeF3X("Remove", {Target.Character})
			Insert.Text = "Succesfully Kicked "..Target.Name
		end
	end)

	Ban.MouseButton1Click:Connect(function()
		if Insert.Text == "all" then
			for _, plr in pairs(GetAllPlayersExceptLocal()) do
				if plr.Character then
					InvokeF3X("Remove", {plr.Character})
				end
			end
			Insert.Text = "All Got Banned"
			return
		end

		local Target = GetPlayerFirstName()
		if not Target then return end

		local GetUserID = Target.UserId
		if Target.Character then
			InvokeF3X("Remove", {Target.Character})
		end

		Insert.Text = Target.Name.." Got Banned"

		game.Players.PlayerAdded:Connect(function(player)
			if player.UserId == GetUserID then
				if player.Character then
					InvokeF3X("Remove", {player.Character})
				end
				Insert.Text = Target.Name.." Tried to rejoin but got kicked lmao"
			end
		end)
	end)


	game.TextChatService.TextChannels.RBXSystem:SendAsync("FE Kick/Ban By MoonVM ")
end;
task.spawn(C_6);
